+#
+# Version catalog — single source of truth for every dependency.
+# Sibling modules reference these via `libs.<alias>` in their
+# build.gradle.kts files, so a bump here propagates everywhere.
+#
+[versions]
+# AGP 8.10+ runs on JDK 21+ (and tolerates 25 via the embedded
+# Kotlin DSL bumped to Kotlin 2.0). Paired with Gradle 8.13.
+agp = "8.10.1"
+kotlin = "2.1.0"
+ksp = "2.1.0-1.0.29"
+coreKtx = "1.15.0"
+material = "1.12.0"
+splashscreen = "1.0.1"
+lifecycle = "2.8.7"
+activityCompose = "1.9.3"
+composeBom = "2024.12.01"
+navCompose = "2.8.5"
+hilt = "2.52"
+hiltNav = "1.2.0"
+hiltCompiler = "1.2.0"
+retrofit = "2.11.0"
+okhttp = "4.12.0"
+kotlinxSerialization = "1.7.3"
+retrofitKotlinxSerialization = "1.0.0"
+# Retrofit 2.11+ ships its own kotlinx-serialization converter; we use
+# the Square-published one which lives in the main retrofit GAV group.
+room = "2.6.1"
+sqlcipher = "4.6.1"
+dataStore = "1.1.1"
+security = "1.1.0-alpha06"
+coil = "2.7.0"
+# BouncyCastle — pulled in by the pre-existing NoiseSession.kt + RumProtocolV2.kt
+# protocol reference files that ship alongside the new modules. Once the ATSAM
+# port lands these files will move into a dedicated :core:mesh module and the
+# dependency moves with them.
+bouncycastle = "1.78.1"
+# Credential Manager — Google's recommended replacement for the
+# legacy GoogleSignIn SDK. Pairs with the googleid helper to
+# request ID tokens.
+credentials = "1.3.0"
+googleId = "1.1.1"
+# WorkManager — used by Phase 2f's signed-prekey rotation worker
+# (PrekeyRotationWorker). Hilt-aware via androidx.hilt:hilt-work which
+# bridges WorkManager's WorkerFactory contract into the Hilt graph.
+workManager = "2.10.0"
+coroutines = "1.9.0"
+junit = "4.13.2"
+junitExt = "1.2.1"
+espresso = "3.6.1"
+
+[libraries]
+# ── Kotlin / coroutines ──────────────────────────────────────────────
+kotlin-coroutines = { module = "org.jetbrains.kotlinx:kotlinx-coroutines-android", version.ref = "coroutines" }
+kotlinx-serialization-json = { module = "org.jetbrains.kotlinx:kotlinx-serialization-json", version.ref = "kotlinxSerialization" }
