+            Divider().background(Color.white.opacity(0.05))
+
+            if let error {
+                Text(error)
+                    .foregroundStyle(.red)
+                    .font(.system(size: 13))
+                    .padding(20)
+            } else if results.isEmpty && !query.isEmpty && !searching {
+                Text("No users found")
+                    .foregroundStyle(.secondary)
+                    .font(.system(size: 13))
+                    .padding(20)
+            } else if results.isEmpty {
