+                        .font(.system(size: 36))
+                        .foregroundStyle(.secondary.opacity(0.5))
+                    Text("Type a username to find someone.")
+                        .foregroundStyle(.secondary)
+                        .font(.system(size: 13))
+                }
+                .padding(.vertical, 40)
+            } else {
