+                    }
+
+                    if isGroup, let members = details?.members, !members.isEmpty {
+                        Divider()
+                        Text("Members").font(.system(size: 13, weight: .semibold))
+                        ForEach(members) { m in
+                            HStack {
+                                AvatarView(
+                                    letter: String(m.username.prefix(1)).uppercased(),
+                                    size: 28,
+                                    urlString: m.avatarPath
+                                )
+                                Text(m.username)
