+            .padding(.vertical, 8)
+            .background(Color.white.opacity(0.05))
+            .clipShape(Capsule())
+            .padding(10)
+
+            if loading {
+                Spacer(); ProgressView(); Spacer()
+            } else {
+                ScrollView {
+                    LazyVStack(spacing: 0) {
+                        ForEach(filtered) { c in
+                            Button(action: { Task { await forward(to: c) } }) {
