+                            .disabled(sending)
+                            Divider()
+                        }
+                    }
+                }
+            }
+
+            if let error {
+                Text(error).foregroundStyle(.red).font(.caption).padding(8)
+            }
+        }
+        .frame(width: 420, height: 520)
+        .task { await load() }
