+
+func (n *Node) getInboundReadTimeout() time.Duration {
+	n.mu.Lock()
+	defer n.mu.Unlock()
+	if n.inboundReadTimeout <= 0 {
+		return streamReadTimeout
+	}
+	return n.inboundReadTimeout
+}
+
+func (n *Node) handleInboundStream(s inboundBridgeStream, remote peer.ID) {
+	accepted := false
+	defer func() {
+		if accepted {
+			_ = s.Close()
+			return
+		}
+		// Malformed, stalled, or over-budget streams are aborted rather than
+		// gracefully closed so unread attacker bytes are discarded immediately.
+		_ = s.Reset()
+	}()
+
+	reservation, ok := n.getInboundLimiter().acquire(remote)
+	if !ok {
+		return
+	}
+	defer reservation.release()
+
+	// Slow-loris guard: fail the whole frame read if the peer stalls. A
+	// deadline setup failure is itself fail-closed because otherwise there is
+	// no bound on how long this reservation can remain live.
+	if err := s.SetReadDeadline(time.Now().Add(n.getInboundReadTimeout())); err != nil {
+		return
+	}
+	r := bufio.NewReader(s)
+
+	// Frame: [4-byte big-endian len][envelope bytes][2-byte idemKey len][idemKey].
+	var lenBuf [4]byte
+	if _, err := io.ReadFull(r, lenBuf[:]); err != nil {
+		return
+	}
+	envLen := int(binary.BigEndian.Uint32(lenBuf[:]))
+	if envLen <= 0 || envLen > maxEnvelopeBytes {
+		return
+	}
+	if !reservation.reserveBytes(int64(envLen)) {
+		return
+	}
+	env := make([]byte, envLen)
+	if _, err := io.ReadFull(r, env); err != nil {
+		return
+	}
+	var keyLenBuf [2]byte
+	if _, err := io.ReadFull(r, keyLenBuf[:]); err != nil {
+		return
+	}
+	keyLen := int(binary.BigEndian.Uint16(keyLenBuf[:]))
+	if keyLen > maxIdempotencyKeyBytes || !reservation.reserveBytes(int64(keyLen)) {
+		return
+	}
+	idem := make([]byte, keyLen)
+	if keyLen > 0 {
+		if _, err := io.ReadFull(r, idem); err != nil {
+			return
+		}
+	}
+	accepted = true
+	// Hand the opaque envelope to Swift. `env` is already the base64 text the
+	// sender wrote (1:1 with the server bridge's envelope_b64 contract).
+	if n.delegate != nil {
+		n.delegate.OnEnvelope(string(env), string(idem))
+	}
+}
+
+func readFull(r *bufio.Reader, buf []byte) (int, error) {
+	total := 0
+	for total < len(buf) {
+		m, err := r.Read(buf[total:])
+		total += m
+		if err != nil {
+			return total, err
+		}
+	}
+	return total, nil
+}
+
+// Send dials/relays to `peerIDStr`, opening a /raven/bridge/1.0.0 stream and
+// writing the opaque envelope. `envelopeB64` is the same base64 string the
+// server bridge used; `idempotencyKey` dedups on the receiver.
+func (n *Node) Send(peerIDStr, envelopeB64, idempotencyKey string) error {
+	n.mu.Lock()
+	h, kdht, ctx, relays := n.host, n.dht, n.ctx, n.relays
+	n.mu.Unlock()
+	if h == nil || kdht == nil {
+		return errors.New("node not started")
+	}
+	env := []byte(envelopeB64)
+	idem := []byte(idempotencyKey)
+	if err := validateOutboundFrame(env, idem); err != nil {
+		return err
+	}
+
+	pid, err := peer.Decode(peerIDStr)
+	if err != nil {
+		return fmt.Errorf("bad peer id: %w", err)
+	}
+
+	// Discover the peer over the DHT if we don't already have addrs (best
+	// effort; short timeout — the relay-circuit fallback below covers the
+	// common mobile case where the peer has no directly dialable address).
+	dctx, dcancel := context.WithTimeout(ctx, 12*time.Second)
+	ai, err := kdht.FindPeer(dctx, pid)
+	dcancel()
+	if err == nil && len(ai.Addrs) > 0 {
+		h.Peerstore().AddAddrs(pid, ai.Addrs, 10*time.Minute)
+	}
+
+	// Relay-circuit fallback: a mobile peer doesn't listen on a dialable
+	// address — it's reachable only THROUGH a relay it reserved a slot on
+	// (AutoRelay). Construct /<relay>/p2p/<relayID>/p2p-circuit for the target
+	// from each configured relay so the swarm can dial it over the circuit.
+	for _, r := range relays {
+		suffix, serr := multiaddr.NewMultiaddr("/p2p/" + r.ID.String() + "/p2p-circuit")
+		if serr != nil {
+			continue
+		}
+		for _, ra := range r.Addrs {
+			h.Peerstore().AddAddrs(pid, []multiaddr.Multiaddr{ra.Encapsulate(suffix)}, 10*time.Minute)
+		}
+	}
+
+	cctx, ccancel := context.WithTimeout(ctx, 30*time.Second)
+	defer ccancel()
+	// Allow dialing through relays (limited/relayed connections).
+	cctx = network.WithAllowLimitedConn(cctx, "raven-bridge")
+	s, err := h.NewStream(cctx, pid, bridgeProtocol)
+	if err != nil {
+		return fmt.Errorf("open stream: %w", err)
+	}
+	defer s.Close()
+
+	var hdr [4]byte
+	binary.BigEndian.PutUint32(hdr[:], uint32(len(env)))
+	if _, err := s.Write(hdr[:]); err != nil {
+		return err
+	}
+	if _, err := s.Write(env); err != nil {
+		return err
+	}
+	var khdr [2]byte
+	binary.BigEndian.PutUint16(khdr[:], uint16(len(idem)))
+	if _, err := s.Write(khdr[:]); err != nil {
+		return err
+	}
+	if _, err := s.Write(idem); err != nil {
+		return err
+	}
+	return nil
+}
+
+func validateOutboundFrame(env, idem []byte) error {
+	if len(env) == 0 {
+		return errors.New("envelope is empty")
+	}
+	if len(env) > maxEnvelopeBytes {
+		return errors.New("envelope too large")
+	}
+	if len(idem) > maxIdempotencyKeyBytes {
+		return errors.New("idempotency key too large")
+	}
+	return nil
+}
+
+// PeerID returns our libp2p peer ID (derived from the RAVEN Ed25519 key).
+func (n *Node) PeerID() string {
+	n.mu.Lock()
+	defer n.mu.Unlock()
+	if n.host == nil {
+		if id, err := peer.IDFromPrivateKey(n.priv); err == nil {
+			return id.String()
+		}
+		return ""
+	}
+	return n.host.ID().String()
+}
+
+// Stop shuts the host down.
+func (n *Node) Stop() error {
+	// Tear down rendezvous invites first, outside n.mu: each owns an ephemeral
+	// host and a relay reservation that must be released, and CancelAllInvites
+	// takes its own lock.
+	n.CancelAllInvites()
+
+	n.mu.Lock()
+	defer n.mu.Unlock()
+	if !n.started {
+		return nil
+	}
+	if n.cancel != nil {
+		n.cancel()
+	}
+	var err error
+	if n.host != nil {
+		err = n.host.Close()
+	}
+	n.started = false
+	if n.delegate != nil {
+		n.delegate.OnStatus(false, "")
+	}
+	return err
+}

