+    /// Situational selection — content stays RavenEnvelopeV1; carrier only.
+    public static func prefer(wifiUp: Bool, peerOnLan: Bool, blePeersNearby: Bool) -> RavenTransportPreference {
+        if wifiUp && peerOnLan { return .directLan }
