+        await MainActor.run {
+            publishStatus = .working
+            lastError = nil
+        }
+        guard
+            let userId = await KeychainService.shared.getUserId(),
+            let deviceId = DeviceIdentityService.shared.fingerprint
+        else {
+            await MainActor.run {
+                publishStatus = .failure
+                lastError = "Sign-in or device identity not ready."
+            }
+            return
+        }
