-"pp.voice.q1.a" = "לא. אודיו משודר חי בלבד, לא מוקלט.";
-"pp.voice.q2.q" = "האם חדרי קול נשמרים או מאורכבים?";
-"pp.voice.q2.a" = "לא. כשהחדר נגמר, שום דבר לא נשמר.";
-"pp.voice.q3.q" = "מי יכול לשמוע אותי כשאני מדבר?";
-"pp.voice.q3.a" = "כל מי שנמצא כרגע בחדר.";
-"pp.voice.q4.q" = "האם אוכל להצטרף לחדרי קול באנונימיות?";
-"pp.voice.q4.a" = "כן. אם מארח החדר מאפשר זאת, ניתן להצטרף באופן אנונימי. תקבל זהות חיה אקראית (למשל, 'Happy Fox') ושם המשתמש האמיתי והפרופיל שלך יישארו מוסתרים מכל המשתתפים.";
-
-// PP Status
-"pp.status.q1.q" = "איך Raven קובע אם אני מקוון?";
-"pp.status.q1.a" = "לפי פעילות האפליקציה. נקודה ירוקה כשהאפליקציה פתוחה ופעילה.";
-"pp.status.q2.q" = "מה פירוש \"נראה לאחרונה\"?";
-"pp.status.q2.a" = "הפעם האחרונה שפתחת את האפליקציה.";
-"pp.status.q3.q" = "האם אוכל להסתיר את הסטטוס המקוון שלי?";
-"pp.status.q3.a" = "כן, בהגדרות פרטיות. אבל אז לא תוכל לראות את הסטטוס של אחרים גם.";
-"pp.status.q4.q" = "האם מעקב פעילות אופציונלי?";
-"pp.status.q4.a" = "סטטוס מקוון: אופציונלי. דוחות קריסה בסיסיים: נאספים אוטומטית.";
-
-// PP Notifications
-"pp.notifications.q1.q" = "אילו נתונים משמשים לשליחת התראות?";
-"pp.notifications.q1.a" = "אסימון המכשיר שלך ותוכן ההתראה (שם השולח, תצוגה מקדימה של הודעה).";
-"pp.notifications.q2.q" = "האם Raven קורא את תוכן ההתראות?";
-"pp.notifications.q2.a" = "השרת מייצר התראות, אז הוא יודע מי שלח מה.";
-"pp.notifications.q3.q" = "האם אוכל לכבות התראות?";
-"pp.notifications.q3.a" = "כן, בהגדרות האפליקציה או בהגדרות iOS.";
-
-// PP Media
-"pp.media.q1.q" = "האם תמונות וסרטונים שהועלו מוצפנים?";
-"pp.media.q1.a" = "מוצפנים בעת ההעלאה. מאוחסנים בשרתי ענן.";
-"pp.media.q2.q" = "כמה זמן מדיה מאוחסנת?";
-"pp.media.q2.a" = "כל עוד הפוסט או ההודעה קיימים.";
-"pp.media.q3.q" = "האם ניתן למחוק מדיה לצמיתות?";
-"pp.media.q3.a" = "מחיקת הפוסט/ההודעה מוחקת את המדיה מהשרתים.";
-"pp.media.q4.q" = "האם צילומי מסך מזוהים או מוגבלים?";
-"pp.media.q4.a" = "iOS יכול לחסום צילומי מסך לתוכן צפייה חד-פעמית. אנחנו מודיעים ליוצר הסטורי אם מזוהה צילום מסך.";
-
-// PP Security
-"pp.security.q1.q" = "איך Raven מגן על נתוני משתמשים?";
-"pp.security.q1.a" = "HTTPS לכל החיבורים, אחסון מוצפן, אימות מאובטח.";
-"pp.security.q2.q" = "האם נתונים מוצפנים במנוחה ובתעבורה?";
-"pp.security.q2.a" = "תעבורה: כן (TLS). במנוחה: תלוי בסוג האחסון.";
-"pp.security.q3.q" = "איך Raven מונע גישה לא מורשית?";
-"pp.security.q3.a" = "התחברות בסיסמה/ביומטריה, נעילת אפליקציה אופציונלית, ניהול הפעלות.";
-"pp.security.q4.q" = "מה קורה במקרה של פריצת נתונים?";
-"pp.security.q4.a" = "נחקור, נתקן את הבעיה ונודיע למשתמשים מושפעים כנדרש בחוק.";
-
-// PP Third Parties
-"pp.thirdparty.q1.q" = "האם Raven משתף נתונים עם צדדים שלישיים?";
-"pp.thirdparty.q1.a" = "Apple (התראות push), Google (כניסה, תכונות AI), RevenueCat (ניהול מנויים) וספק אירוח הענן שלנו.";
-"pp.thirdparty.q2.q" = "האם נאספים ניתוחים או דוחות קריסה?";
-"pp.thirdparty.q2.a" = "כן, דוחות קריסה אנונימיים לתיקון באגים.";
-"pp.thirdparty.q3.q" = "האם נעשה שימוש בפרסומות או עוקבים?";
-"pp.thirdparty.q3.a" = "ללא פרסומות. ללא עוקבים של צד שלישי.";
-"pp.thirdparty.q4.q" = "האם Raven מוכר נתוני משתמשים?";
-"pp.thirdparty.q4.a" = "לא.";
-"pp.thirdparty.q5.q" = "האם ההודעות או הפוסטים שלי נשלחים לספקי AI?";
-"pp.thirdparty.q5.a" = "רק כאשר אתה משתמש באופן מפורש בתכונות AI (כמו 'שאל את Gemini' או 'תמלול קולי'). הפוסט הספציפי או קובץ השמע נשלח בצורה מאובטחת ל-Google לעיבוד. ההודעות הפרטיות שלך לעולם לא נשלחות ל-AI ולא משמשות לאימון מודלים ציבוריים.";
-
-// PP User Rights
-"pp.rights.q1.q" = "האם אוכל לבקש העתק של הנתונים שלי?";
-"pp.rights.q1.a" = "כן, שלח דוא\"ל ל-privacy@raven-messager.com.";
-"pp.rights.q2.q" = "האם אוכל למחוק את החשבון וכל הנתונים שלי?";
-"pp.rights.q2.a" = "כן, בהגדרות > חשבון > סגירת חשבון.";
-"pp.rights.q3.q" = "כמה זמן לוקחת המחיקה?";
-"pp.rights.q3.a" = "מיידי מהאפליקציה. גיבויי שרת מנוקים תוך 30 יום.";
-"pp.rights.q4.q" = "מה קורה לנתונים שלי אחרי מחיקת החשבון?";
-"pp.rights.q4.a" = "הנתונים שלך נמחקים. הודעות ששלחת לאחרים נשארות בהיסטוריה שלהם.";
-
-// PP Legal
-"pp.legal.q1.q" = "האם Raven עומד ב-GDPR?";
-"pp.legal.q1.a" = "אנחנו פועלים לפי עקרונות GDPR: מינימיזציית נתונים, הסכמת משתמש, זכות למחיקה.";
-"pp.legal.q2.q" = "האם Raven עומד בחוקי פרטיות מקומיים?";
-"pp.legal.q2.a" = "אנחנו מנסים לעמוד בחוקים המתאימים באזורים בהם אנו פועלים.";
-"pp.legal.q3.q" = "איך מתקשרים שינויים במדיניות הפרטיות?";
-"pp.legal.q3.a" = "התראה באפליקציה ומדיניות מעודכנת באפליקציה.";
-"pp.legal.q4.q" = "איך אוכל לפנות ל-Raven בנוגע לבעיות פרטיות?";
-"pp.legal.q4.a" = "דוא\"ל ל-privacy@raven-messager.com";
