+
+    pub fn decode_wire(raw: &[u8]) -> Result<Self, String> {
+        if raw.len() < CONTACT_ACCEPT_WIRE.len() + 16 + 64 + 32 {
+            return Err("contact accept wire short".into());
+        }
+        if &raw[..CONTACT_ACCEPT_WIRE.len()] != CONTACT_ACCEPT_WIRE {
