+fn bytes_to_seed(bytes: &[u8]) -> Result<[u8; 32], IdentityStoreError> {
+    if bytes.len() != 32 {
+        return Err(IdentityStoreError::Corrupt);
+    }
+    let mut seed = [0u8; 32];
+    seed.copy_from_slice(bytes);
+    Ok(seed)
