+    if let Some((mut seed, backend)) = load_seed_with_migrate(data_dir)? {
+        let id = Identity::from_seed(&seed);
+        seed.zeroize();
+        return Ok((id, backend));
+    }
+    let id = Identity::generate();
+    let mut seed = id.seed_bytes();
+    let backend = store_seed(data_dir, &seed)?;
+    seed.zeroize();
+    Ok((id, backend))
