+    impl ProtectedPrekeyBackend for MemoryProtectedBackend {
+        fn get(&self, account: &str) -> Result<Option<Vec<u8>>, PrekeyLifecycleError> {
+            Ok(self
+                .values
+                .lock()
+                .map_err(|_| PrekeyLifecycleError::LockFailed)?
