+
+        fn put(&self, account: &str, value: &[u8]) -> Result<(), PrekeyLifecycleError> {
+            self.values
+                .lock()
+                .map_err(|_| PrekeyLifecycleError::LockFailed)?
+                .insert(account.into(), value.to_vec());
+            Ok(())
+        }
+    }
