+    fn counter_zero_matches_vector() {
+        let k: Vec<u8> = (0u8..32).collect();
+        let tag = derive(&k, 1700000000, 0);
+        assert_eq!(hex::encode(tag), "611432077911411fb5470eb80f1ff119");
+    }
+}

