+//! RavenStoreObjectV1 — opaque custody + rotating mailbox tags.
+//!
+//! Spec: `protocol/RAVEN_STORE_OBJECT_V1.md`
+
+use hmac::{Hmac, Mac};
+use serde::{Deserialize, Serialize};
+use sha2::Sha256;
+
+use crate::bridge::authenticated_object_digest;
+use crate::envelope::Envelope;
