+            message_id_hex: String,
+            created_at_ms: u64,
+            expires_at_ms: u64,
+            flags: u16,
+            packed_envelope_hex: String,
+            custody_sig_hex: Option<String>,
+        }
+        let mut mb = Self::new(max_per_tag);
+        let Ok(metadata) = std::fs::symlink_metadata(path) else {
