+fn schedule_path(
+    sim: &mut Simulation,
+    path: &[usize],
+    start: u64,
+    spacing: u64,
+    latency: u64,
+) -> u64 {
+    assert!(path.len() >= 2);
+    let mut at = start;
+    for pair in path.windows(2) {
+        sim.schedule_contact(at, pair[0], pair[1], ContactProfile::reliable(latency));
+        at += spacing;
+    }
+    at
+}
+
+fn schedule_reverse_path(
+    sim: &mut Simulation,
+    path: &[usize],
+    start: u64,
+    spacing: u64,
+    latency: u64,
+) -> u64 {
+    let mut at = start;
+    for pair in path.windows(2).rev() {
+        sim.schedule_contact(at, pair[0], pair[1], ContactProfile::reliable(latency));
+        at += spacing;
+    }
+    at
+}
